//! Python `mimetypes.guess_type(name)[0]` for `page_upload` entries.
//!
//! Why: each uploaded file carries the MIME type Python guessed from its
//! basename, and the page sees it, so the Rust server must guess the same.
//! What: `mimetypes.tsv` holds Python 3.12's strict `suffix_map`,
//! `encodings_map` and `types_map`, as loaded on the capture host
//! (regenerated by `tests/fixtures/capture/capture_mcp.py`). [`guess_type`]
//! ports `MimeTypes.guess_type`: URL scheme split (with `data:` handling),
//! suffix rewrites, a case-sensitive encoding suffix, then a lowercased type
//! suffix.
//! Test: `mime_guesses_match_python` below; the upload replay in
//! `tests/parity_mcp.rs` covers `.txt`, `.png`, `.JSON`, `.tar.gz` and no suffix.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("mimetypes.tsv");

struct Maps {
    suffix: HashMap<&'static str, &'static str>,
    encoding: HashMap<&'static str, &'static str>,
    types: HashMap<&'static str, &'static str>,
}

fn maps() -> &'static Maps {
    static MAPS: OnceLock<Maps> = OnceLock::new();
    MAPS.get_or_init(|| {
        let mut m = Maps {
            suffix: HashMap::new(),
            encoding: HashMap::new(),
            types: HashMap::new(),
        };
        for line in TABLE.lines().filter(|l| !l.starts_with('#')) {
            let mut cols = line.split('\t');
            let (Some(kind), Some(key), Some(value)) = (cols.next(), cols.next(), cols.next())
            else {
                continue;
            };
            let map = match kind {
                "suffix" => &mut m.suffix,
                "encoding" => &mut m.encoding,
                _ => &mut m.types,
            };
            map.insert(key, value);
        }
        m
    })
}

/// `posixpath.splitext`: the suffix starts at the last dot of the last
/// component, unless only dots precede it there.
fn splitext(p: &str) -> (&str, &str) {
    let sep = p.rfind('/').map_or(0, |i| i + 1);
    let Some(dot) = p.rfind('.') else {
        return (p, "");
    };
    if dot < sep || p[sep..dot].bytes().all(|b| b == b'.') {
        return (p, "");
    }
    (&p[..dot], &p[dot..])
}

const USES_PARAMS: &[&str] = &[
    "", "ftp", "hdl", "prospero", "http", "imap", "https", "shttp", "rtsp", "rtsps", "rtspu",
    "sip", "sips", "mms", "sftp", "tel",
];

/// `urllib.parse.urlparse(url)`'s scheme (lowercased) and path, for a name
/// with no `/`.
fn url_path(url: &str) -> (String, &str) {
    let (scheme, rest) = match url.split_once(':') {
        Some((s, rest))
            if s.as_bytes().first().is_some_and(u8::is_ascii_alphabetic)
                && s.bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b"+-.".contains(&b)) =>
        {
            (s.to_ascii_lowercase(), rest)
        }
        _ => (String::new(), url),
    };
    let rest = rest.split('#').next().unwrap_or(rest);
    let mut path = rest.split('?').next().unwrap_or(rest);
    if USES_PARAMS.contains(&scheme.as_str())
        && let Some(i) = path.find(';')
    {
        path = &path[..i];
    }
    (scheme, path)
}

/// `mimetypes.guess_type(name)[0]` (strict).
pub fn guess_type(name: &str) -> Option<String> {
    let (scheme, path) = url_path(name);
    let url = if scheme.len() > 1 { path } else { name };
    if scheme == "data" {
        let comma = url.find(',')?;
        let head = &url[..comma];
        let kind = head.split(';').next().unwrap_or(head);
        if kind.contains('=') || !kind.contains('/') {
            return Some("text/plain".to_owned());
        }
        return Some(kind.to_owned());
    }
    let m = maps();
    let (b, e) = splitext(url);
    let (mut base, mut ext) = (b.to_owned(), e.to_owned());
    while let Some(sub) = m.suffix.get(ext.to_lowercase().as_str()) {
        let joined = format!("{base}{sub}");
        let (b, e) = splitext(&joined);
        (base, ext) = (b.to_owned(), e.to_owned());
    }
    if m.encoding.contains_key(ext.as_str()) {
        let (_, e) = splitext(&base);
        ext = e.to_owned();
    }
    m.types
        .get(ext.to_lowercase().as_str())
        .map(|t| (*t).to_owned())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mime_guesses_match_python() {
        let cases = [
            ("a.txt", Some("text/plain")),
            ("b.png", Some("image/png")),
            ("X.JSON", Some("application/json")),
            ("t.tar.gz", Some("application/x-tar")),
            ("t.tgz", Some("application/x-tar")),
            ("noext", None),
            (".bashrc", None),
            ("a.txt?x", None),
            ("ab:x.png?y", Some("image/png")),
            ("http:x;y.png", None),
            ("..x", None),
            ("a.SVGZ", Some("image/svg+xml")),
            ("f.tar.Z", Some("application/x-tar")),
            ("data:image/gif;base64,R0", Some("image/gif")),
        ];
        for (name, want) in cases {
            assert_eq!(guess_type(name).as_deref(), want, "{name}");
        }
    }
}
